class TasksHandler:HttpMessageHandler {
 public int Requests;public bool Hidden=true;public string Match,Method;public HttpStatusCode Code=HttpStatusCode.OK;
 protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){
  Requests++;Method=request.Method.Method;Match=request.Headers.Contains("If-Match")?request.Headers.GetValues("If-Match").Single():null;
  string body="{}",url=request.RequestUri.AbsoluteUri;if(Code==HttpStatusCode.OK){
   if(request.Method!=HttpMethod.Get)body="{\"id\":\"a\",\"title\":\"修改后\",\"etag\":\"next\"}";
   else if(url.Contains("users/@me"))body=url.Contains("pageToken")?"{\"items\":[{\"id\":\"second\",\"title\":\"个人\"}]}":"{\"items\":[{\"id\":\"first\",\"title\":\"我的任务\"}],\"nextPageToken\":\"list-next\"}";
   else{Hidden=Hidden&&url.Contains("showHidden=true")&&url.Contains("showCompleted=true");body=url.Contains("pageToken")?"{\"items\":[{\"id\":\"b\",\"title\":\"已完成\",\"status\":\"completed\"}]}":"{\"items\":[{\"id\":\"a\",\"title\":\"测试\",\"due\":\"2026-10-27T00:00:00.000Z\",\"etag\":\"revision\"}],\"nextPageToken\":\"task-next\"}";}
  }
  return Task.FromResult(new HttpResponseMessage(Code){Content=new StringContent(body)});
 }
}
